  3244          if (hts_idx_push(fp->idx, tid, v->pos, v->pos + v->rlen, bgzf_tell(fp->fp.bgzf), 1) < 0)
  3245              return -1;
  3246      }
  3247
  3248      return ret==fp->line.l ? 0 : -1;
  3249  }
